/* Narrative reports are generated by explicit local rules; no AI service is called. */
(function(){
'use strict';
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ko=gz=>Array.from(gz).map(c=>Saju.KO[c]).join('');
window.mountInsights=function(r){
 const forecast=Saju.forecast(r,r.input.gender);let selected='personality',cycle=forecast.daeun?.cycles.findIndex(c=>c.current)??-1;if(cycle<0)cycle=0;
 document.querySelectorAll('.detail-analysis').forEach(node=>node.remove());
 const baseData=SajuReport.build(r,forecast,cycle);
 // ① 내 사주 한눈에 보기 (요약 + 키워드)
 const summarySection=document.createElement('section');summarySection.className='saju-summary';summarySection.setAttribute('aria-labelledby','summary-heading');
 summarySection.innerHTML=`<div class="summary-head"><span class="eyebrow">AT A GLANCE</span><h2 id="summary-heading">내 사주 한눈에 보기</h2></div><p class="summary-text">${safe(baseData.summary.text)}</p><div class="summary-keywords" aria-label="핵심 키워드">${baseData.summary.keywords.map(k=>`<span class="summary-chip">${safe(k)}</span>`).join('')}</div>`;
 document.querySelector('#result-content .result-grid').before(summarySection);
 const section=document.createElement('section');section.className='insights';section.setAttribute('aria-labelledby','insights-heading');
 section.innerHTML=`<div class="insights-heading"><div><span class="eyebrow">YOUR OWN STORY, IN DEPTH</span><h2 id="insights-heading">분야별 상세 해설</h2></div><span class="insights-flower" aria-hidden="true">✳</span></div><div class="insight-tabs" role="tablist" aria-label="사주 해설 주제">${[['personality','성격','✧'],['love','연애','♡'],['career','일과 재물','◆'],['daeun','시기별 흐름','⌁'],['annual','올해·내년','◷']].map(([id,label,icon])=>`<button id="tab-${id}" role="tab" aria-controls="insight-${id}" aria-selected="${id===selected}" tabindex="${id===selected?0:-1}" data-tab="${id}"><span aria-hidden="true">${icon}</span>${label}</button>`).join('')}</div>${['personality','love','career','daeun','annual'].map(id=>`<div id="insight-${id}" role="tabpanel" aria-labelledby="tab-${id}" ${id===selected?'':'hidden'}></div>`).join('')}<p class="report-footnote">전통 명리학의 상징을 조합한 규칙 기반 해설입니다. AI 생성 상담이나 사건 예측은 아니며, 실제 성격과 관계는 경험·환경·선택에 따라 달라집니다.</p>`;
 document.querySelector('#result-content .result-grid').before(section);
 const chapters=report=>`<div class="report-chapters">${report.chapters.map((c,i)=>`<section class="report-chapter"><span class="chapter-number">${String(i+1).padStart(2,'0')}</span><div><h4>${safe(c.title.replace(/^\d+\.\s*/,''))}</h4>${c.paragraphs.map(p=>`<p>${safe(p)}</p>`).join('')}</div></section>`).join('')}</div>`;
 // ③ 해석 근거 보기: 해당 해설이 사용한 원국 데이터만 접어서 보여준다
 const evidenceBlock=key=>{const items=baseData.evidence[key];if(!items)return '';return `<details class="evidence-fold"><summary>이 해설의 근거 보기 <span>+</span></summary><ul>${items.map(it=>`<li>${safe(it)}</li>`).join('')}</ul></details>`;};
 const report=(data,label,evKey)=>`<article class="panel long-report"><div class="report-cover"><span class="reading-label">${label}</span><h3>${safe(data.title)}</h3><p class="report-opening">${safe(data.lead)}</p></div>${chapters(data)}${evidenceBlock(evKey)}</article>`;
 function loveReport(data){return report(data.basic||data,'LOVE · 나의 관계 성향','love')+`<details class="evidence-fold"><summary>연애 해석 근거 자세히 보기 <span>+</span></summary>${chapters(data.technical||data)}</details>`;}
 function daeun(data){const d=forecast.daeun;if(!d)return `<article class="panel empty-daeun"><span class="reading-label">TEN YEARS, ONE CHAPTER</span><h3>대운을 포함한 이야기를 읽으려면</h3><p>입력 화면에서 전통 해석 기준을 선택해주세요. 순행·역행과 시작 시각을 계산한 뒤, 원국과 함께 각 구간의 흐름을 풀어드릴게요.</p><a class="button primary" href="#form">전통 해석 기준 선택 <span>→</span></a></article>`;
 return `<article class="panel daeun-panel long-report"><div class="panel-title-row"><div><span class="reading-label">TEN YEARS, ONE CHAPTER</span><h3>열 해마다 펼쳐지는 새로운 장.</h3></div><span class="local-badge">${d.forward?'순행 →':'← 역행'}${d.approximate?' · 시작 시점 참고값':''}</span></div><p class="insight-lead">첫 대운은 출생 후 ${d.years}년 ${d.months}개월 ${d.days}일 ${d.hours}시간에 시작합니다. 구간을 누르면 원국과 함께 읽은 이야기가 이어져요.</p>${d.beforeStart?'<p class="soft-callout">지금은 첫 대운이 시작되기 전입니다.</p>':d.afterEnd?'<p class="soft-callout">현재 시점은 표시된 9개 대운 구간 이후입니다.</p>':''}<div class="daeun-timeline" role="group" aria-label="대운 구간 선택">${d.cycles.map((c,i)=>`<button class="cycle ${cycle===i?'selected':''} ${c.current?'current':''}" data-cycle="${i}" aria-pressed="${cycle===i}" aria-label="${c.start} 시작 ${ko(c.gan+c.zhi)} 대운${c.current?', 현재 구간':''}"><span class="cycle-current">${c.current?'지금의 대운':'만 '+c.age+'세 시작'}</span><strong>${ko(c.gan+c.zhi)}</strong><span class="cycle-han">${c.gan}${c.zhi}</span><span>${c.start.slice(0,4)}–${c.end.slice(0,4)}</span></button>`).join('')}</div><div class="cycle-detail report-cover" aria-live="polite"><span class="small-label">${data.start} ~ ${data.end} 직전 · ${data.current?'현재 구간':'선택한 구간'}</span><h4>${safe(data.title)}</h4><p>${safe(data.lead)}</p></div>${chapters(data)}${d.approximate?'<p class="notice">정확한 출생 시각이 없어 대운 시작 시점은 참고값이에요. 출생 시각에 따라 전환일이 달라질 수 있어요.</p>':''}</article>`;}
 function annual(reports){return `<div class="annual-report-intro"><span class="eyebrow">THIS YEAR & THE NEXT</span><h3>올해에서 내년으로,<br>무엇을 이어가고 달리 볼까요?</h3><p>${forecast.year}년과 ${forecast.year+1}년을 각각 풀어드려요. 해의 흐름은 입춘부터 다음 입춘까지로 읽습니다.</p></div>${reports.map((a,i)=>`<article class="panel long-report annual-long"><div class="report-cover"><span class="reading-label">${i?'NEXT YEAR':'THIS YEAR'} · ${a.year} ${ko(a.gan+a.zhi)}(${a.gan}${a.zhi})</span><h3>${safe(a.title)}</h3><p class="report-opening">${safe(a.lead)}</p></div>${chapters(a)}</article>`).join('')}`;}
 function render(){const data=SajuReport.build(r,forecast,cycle);const html={personality:()=>report(data.personality,'PERSONALITY · '+Saju.KO[r.dayGan]+r.dayGan,'personality'),love:()=>loveReport(data.love),career:()=>report(data.career,'WORK & WEALTH · 일과 재물','career'),daeun:()=>daeun(data.daeun),annual:()=>annual(data.annual)};for(const id of Object.keys(html)){const panel=section.querySelector('#insight-'+id);panel.hidden=id!==selected;if(id===selected)panel.innerHTML=html[id]();}section.querySelectorAll('[role=tab]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.tab===selected));b.tabIndex=b.dataset.tab===selected?0:-1;});}
 section.addEventListener('click',event=>{const tab=event.target.closest('[data-tab]');if(tab){selected=tab.dataset.tab;render();return;}const c=event.target.closest('[data-cycle]');if(c){const scroll=section.querySelector('.daeun-timeline').scrollLeft;cycle=Number(c.dataset.cycle);render();section.querySelector('.daeun-timeline').scrollLeft=scroll;section.querySelector(`[data-cycle="${cycle}"]`).focus({preventScroll:true});}});
 section.querySelector('[role=tablist]').addEventListener('keydown',event=>{const tabs=[...section.querySelectorAll('[role=tab]')],idx=tabs.indexOf(event.target);if(idx<0)return;let next;if(event.key==='ArrowRight')next=(idx+1)%tabs.length;else if(event.key==='ArrowLeft')next=(idx+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();selected=tabs[next].dataset.tab;render();tabs[next].focus();});render();
 mountDetailAnalysis(r,baseData);
};

// ④ 상세 사주 분석: 계산되는 항목(형충회합)과 미계산 항목(신살 등)을 구분해 표시
function mountDetailAnalysis(r,data){
 const ZHI=Saju.ZHI;const kz=z=>Saju.KO[z]+'('+z+')';
 // 지지 관계: 원본 문서 6.4 정의 기준. 네 지지에서 실제로 성립하는 조합만 표시.
 const branches=r.pillars.map((p,i)=>p?{z:p.zhi,label:['시주','일주','월주','년주'][i]}:null).filter(Boolean);
 const SIXHARM=['子丑','寅亥','卯戌','辰酉','巳申','午未'];const found={harmony:[],clash:[]};
 for(let a=0;a<branches.length;a++)for(let b=a+1;b<branches.length;b++){const x=branches[a].z,y=branches[b].z;const pair=[x,y];if(SIXHARM.some(s=>s.includes(x)&&s.includes(y)&&x!==y))found.harmony.push(`${kz(x)}·${kz(y)} 육합`);if(Math.abs(ZHI.indexOf(x)-ZHI.indexOf(y))===6)found.clash.push(`${kz(x)}·${kz(y)} 육충`);}
 const detail=document.createElement('section');detail.className='detail-analysis';detail.setAttribute('aria-label','상세 사주 분석');
 const rel=found.harmony.length||found.clash.length?`${found.harmony.concat(found.clash).join(', ')}이(가) 확인돼요. 합은 잇고 조율하는 상징, 충은 다시 조정하는 상징으로 읽되 좋고 나쁨으로 단정하지 않아요.`:'확인된 지지 사이에서 이 해설이 확인하는 직접적인 육합·육충은 나타나지 않아요. 조용한 사주라는 뜻은 아닙니다.';
 detail.innerHTML=`<details class="detail-fold"><summary class="detail-summary"><span class="eyebrow">DETAILED CHART</span>상세 사주 분석 (전문 근거) <span class="detail-plus">+</span></summary>
 <div class="detail-body">
 <p class="detail-note">아래는 계산된 전문 정보예요. 위 해설과 같은 데이터에서 나왔습니다. 원국표와 오행 분포, 지장간·12운성 및 계산 기준을 여기서 확인할 수 있어요.</p>
 <div class="detail-card"><h4>형충회합 (지지 관계)</h4><p>${safe(rel)}</p></div>
 <div class="detail-card"><h4>추가 해석 기준이 필요한 항목</h4><p>신살(도화살·역마살 등), 용신 확정, 신강/신약, 월별 세운, 궁합은 이번 버전에서 <strong>계산하지 않았어요</strong>. ‘해당 없음’이 아니라 <strong>아직 계산하지 않은 항목</strong>이라는 뜻이에요. 구현과 검증이 끝난 결과만 표시하고 있어요.</p></div>
 <div class="detail-card"><h4>시주 경계에 대한 참고</h4><p>이 서비스는 자시를 23:00~01:00, 일주 변경을 자정(00:00)으로 계산해요. 원본 문서는 진태양시 기준 23:30~01:29를 자시로 보고 조자시(00:00~01:29)에 익일 일주를 적용하는 다른 방식이라, 자정 전후 출생은 결과가 달라질 수 있어요. 시간대만 고른 경우에는 분 단위 보정을 적용하지 않았습니다.</p></div>
 <div class="detail-chart-slot"></div>
 </div></details>`;
 document.querySelector('.result-end').before(detail);
 // 기존 원국표·오행 표(.result-grid)와 지장간/12운성/계산근거 패널을 상세 분석 안으로 옮겨, 기본 화면은 해설 중심이 되게 한다
 const slot=detail.querySelector('.detail-chart-slot');const grid=document.querySelector('#result-content .result-grid');if(grid)slot.appendChild(grid);
 document.querySelectorAll('#result-content > .details-panel').forEach(panel=>slot.appendChild(panel));
}
})();
